using ECommerce.Application.DTOs.Order;
using ECommerce.Domain.Entities;
using Microsoft.AspNetCore.Identity;
using Microsoft.AspNetCore.Identity.EntityFrameworkCore;
using Microsoft.EntityFrameworkCore;
using System.Collections.Generic;

namespace ECommerce.Infrastructure.Persistence;

public class AppDbContext : IdentityDbContext<User>
{
    //database context that EF Core uses
   
        public AppDbContext(DbContextOptions<AppDbContext> options)
            : base(options)
        {
        }


    public DbSet<Product> Products => Set<Product>();
    public DbSet<Category> Categories => Set<Category>();
    public DbSet<Order> Orders => Set<Order>();
    public DbSet<CartItem> CartItems => Set<CartItem>();
    public DbSet<Publish> Publishes => Set<Publish>();
    public DbSet<WishlistItem> WishlistItems => Set<WishlistItem>();
    public DbSet<Contact> Contacts => Set<Contact>();

    private static readonly DateTime SeedDate = new DateTime(2026, 10, 29, 0, 0, 0, DateTimeKind.Utc);

    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        base.OnModelCreating(modelBuilder); 

        modelBuilder.Entity<Product>()
         .Property(p => p.Price)
         .HasPrecision(18, 2);

        // Catalogue indexes: default sort, category and top-rated listings, price and date filters.
        modelBuilder.Entity<Product>().HasIndex(p => p.CreatedAt).IsDescending();
        modelBuilder.Entity<Product>().HasIndex(p => new { p.CategoryId, p.CreatedAt });
        modelBuilder.Entity<Product>().HasIndex(p => new { p.TopRated, p.CreatedAt });
        modelBuilder.Entity<Product>().HasIndex(p => p.Price);
        modelBuilder.Entity<Product>().HasIndex(p => p.PublishDate);

        modelBuilder.Entity<OrderItem>()
            .Property(oi => oi.Price)
            .HasPrecision(18, 2);

        modelBuilder.Entity<CartItem>()
            .ToTable("CartItem");

        modelBuilder.Entity<CartItem>()
            .Property(c => c.Price)
            .HasPrecision(18, 2);

        // CartItem.UserId holds either a user id or a guest key ("guest:<guid>"), so it is not a foreign key.
        modelBuilder.Entity<CartItem>().Ignore(c => c.User);
        modelBuilder.Entity<CartItem>().HasIndex(c => c.UserId);

        modelBuilder.Entity<CartItem>()
            .HasOne(c => c.Product)
            .WithMany()
            .HasForeignKey(c => c.ProductId)
            .OnDelete(Microsoft.EntityFrameworkCore.DeleteBehavior.Restrict);

        modelBuilder.Entity<WishlistItem>()
            .ToTable("WishlistItem");

        modelBuilder.Entity<WishlistItem>()
            .HasOne(w => w.User)
            .WithMany()
            .HasForeignKey(w => w.UserId)
            .OnDelete(Microsoft.EntityFrameworkCore.DeleteBehavior.Cascade);

        modelBuilder.Entity<WishlistItem>()
            .HasOne(w => w.Product)
            .WithMany()
            .HasForeignKey(w => w.ProductId)
            .OnDelete(Microsoft.EntityFrameworkCore.DeleteBehavior.Restrict);

        // Map relationship explicitly (optional for guest checkout)
        modelBuilder.Entity<Order>()
            .HasOne(o => o.User)
            .WithMany()
            .HasForeignKey(o => o.UserId)
            .IsRequired(false);

        modelBuilder.Entity<Order>()
            .Property(o => o.DeliveryFee)
            .HasPrecision(18, 2);

        modelBuilder.Entity<Publish>()
            .ToTable("Publish");
        modelBuilder.Entity<Contact>()
            .ToTable("Contact");
        modelBuilder.Entity<Publish>()
            .HasOne(p => p.User)
            .WithMany()
            .HasForeignKey(p => p.UserId)
            .OnDelete(Microsoft.EntityFrameworkCore.DeleteBehavior.Cascade);

        // Catalogue seed. Ids start at 1; dates are fixed so migrations stay stable.
        // Top-rated books (ids from 1). Prices other than أرخبيل الملوك are provisional.
        modelBuilder.Entity<Category>().HasData(
            new { Id = 1, Name = "اجتماعي ودراما", CreatedAt = SeedDate },
            new { Id = 2, Name = "فانتازيا وخيال علمي", CreatedAt = SeedDate },
            new { Id = 3, Name = "جريمة وغموض وإثارة", CreatedAt = SeedDate },
            new { Id = 4, Name = "رومانسي", CreatedAt = SeedDate },
            new { Id = 5, Name = "تدريب وهوايات", CreatedAt = SeedDate },
            new { Id = 6, Name = "نفسي", CreatedAt = SeedDate },
            new { Id = 7, Name = "تاريخي وسير", CreatedAt = SeedDate },
            new { Id = 8, Name = "فكر وثقافة", CreatedAt = SeedDate },
            new { Id = 9, Name = "رعب", CreatedAt = SeedDate }
        );
        modelBuilder.Entity<Product>().HasData(
            new { Id = 1, Name = "بعد فارق", Price = 130m, Stock = 10, Description = "رواية فانتازيا بأبعاد فلسفية ونفسية. بين «عبّار» و«فارق» تجد نفسك في رحلة تواجه فيها كل ما تهرب منه، بلا سبيل للفرار من الحقيقة. رحلة مليئة بالخبايا والأسرار بين الحقيقة والزيف، والتعلّق والهروب، هدفها الوصول إلى الحقيقة وحدها.", CategoryId = 1, ImageUrl = "/images/products/baad-fariq.webp", Author = "نوران بسيوني", PublishDate = SeedDate, TopRated = true, CreatedAt = SeedDate },
            new { Id = 2, Name = "أرخبيل الملوك", Price = 130m, Stock = 10, Description = "تجربة فانتازيا ليست بعيدة عن واقعنا؛ فالحياة مليئة باختبارات سهلة وصعبة، وما يبدو سهلًا قد يحمل جوهر الصعوبة. بين الاختيارات ومعرفة الحقيقة التي تتغيّر مع زيادة الوعي تتشكّل رحلتنا في «أرخبيل الملوك»: رحلة عالية المخاطر بين البقاء والتحرر، تجمع الحركة المكثفة بالأسئلة الفلسفية العميقة.", CategoryId = 2, ImageUrl = "/images/products/arkhabil-el-molouk.webp", Author = "ممدوح عماد", PublishDate = SeedDate, TopRated = true, CreatedAt = SeedDate },
            new { Id = 3, Name = "طيف نجاة", Price = 130m, Stock = 10, Description = "بين أعباء الحياة وسباتها المستمر والتوغل في أحلام الآخرين، نفقد جزءًا من أرواحنا ونغدو أحياءً بأجساد هامدة. لكن ماذا لو قررت كسر هذه الدائرة وبدأت رحلتك وفق قواعدك وأحلامك؟ رحلة تكون فيها البطل، تبحث خلالها عن معنى لحياتك وعن ذاتك الحقيقية.", CategoryId = 1, ImageUrl = "/images/products/tayf-najah.webp", Author = "آية المنشاوي", PublishDate = SeedDate, TopRated = true, CreatedAt = SeedDate },
            new { Id = 4, Name = "لوحة أخيرة", Price = 130m, Stock = 10, Description = "تنقلب حياة طبيب نفسي ناجح بعد وفاة والدته، الرسامة الشهيرة المنعزلة، حين يكتشف بالصدفة تسجيلات قديمة ودفاتر تخفي أسرارًا لم يعرفها عنها من قبل. رواية عن الفقد والذاكرة، وعمّا تخبئه اللوحات خلف ألوانها.", CategoryId = 1, ImageUrl = "/images/products/lawha-akhira.webp", Author = "علياء المنشاوي", PublishDate = SeedDate, TopRated = true, CreatedAt = SeedDate },
            new { Id = 5, Name = "حلقة الذنب", Price = 130m, Stock = 10, Description = "ليست مجموعة قصص وحسب، بل نسيج متشابك بين الدراما والفانتازيا: رحلة بخمس تجارب مختلفة مع الشعور بالذنب، حين يتحول من سؤال بريء ينم عن رغبة صاحبه في أن يصبح شخصًا أفضل إلى حلقة مفرغة لا تنتهي من شعور يأكله ببطء. ليس بالضرورة أن تدخل حلقة الذنب بقرار واعٍ.", CategoryId = 1, ImageUrl = "/images/products/halaqat-al-dhanb.webp", Author = "ممدوح عماد، نوران بسيوني، رانا رؤوف، آية المنشاوي", PublishDate = SeedDate, TopRated = true, CreatedAt = SeedDate },
            new { Id = 6, Name = "طلبك مرفوض", Price = 130m, Stock = 10, Description = "كل مرة تتعرض فيها للرفض وتنغلق على نفسك وتسألها: لماذا اخترت أن أكون في هذا المكان؟ تجد إجابة واحدة في انتظارك كل مرة. رواية عن الرفض والإصرار، وعن البحث عن مكانك الحقيقي.", CategoryId = 4, ImageUrl = "/images/products/talabak-marfoud.webp", Author = "رانا رؤوف", PublishDate = SeedDate, TopRated = true, CreatedAt = SeedDate },
            new { Id = 7, Name = "cerca trova", Price = 400m, Stock = 10, Description = "“Cerca Trova” is a gripping international thriller inspired by true stories from the world of humanitarian work. The novel follows an international delegate dedicated to Restoring Family Links, searching for relatives separated by war, disasters, and forced displacement.\n\nFrom conflict zones to fragile border crossings, each mission is a race against time, where a single document, a forgotten name, or a faint clue can reunite a family or close a chapter forever.\nCombining thrill, adventure, and deep emotional resonance, Cerca Trova transforms real humanitarian experiences into compelling fiction that is both fast-paced and profoundly human", CategoryId = 1, ImageUrl = "/images/products/9789778203295.webp", Author = "تامر أحمد", PublishDate = new DateTime(2026, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789778203295", Pages = 552, Size = "14×20" },
            new { Id = 8, Name = "A fire with no spark", Price = 420m, Stock = 10, Description = "Vessels have sunk. Chaos has fallen. The rainy season has begun.\n\nAmid terrified survivors and mercenaries scrambling for escape,\nmadra is running low, and shadowed tunnels lead toward unknown fates.\n\nOne choice could save them all, or turn everything to ash.\n\nThis is not the end of the journey.\nThis is the moment of reckoning.\n\nWill Adam face the cost of his decision?\nWhat became of Rawan?\nAnd will Mike return?\n\nWho will survive… and who will be claimed by the living fire?", CategoryId = 2, ImageUrl = "/images/products/9789778203400.webp", Author = "د. خوله حمدي", PublishDate = new DateTime(2026, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789778203400", Pages = 506, Size = "14×20" },
            new { Id = 9, Name = "اتنين فى واحد", Price = 260m, Stock = 10, Description = "ماذا لو تحقّقت أمنيتك المستحيلة؟\nوماذا لو اكتشفت أن تحقيقها له ثمن؟\nزوج أناني يرى الزواج عبئًا لا يُحتمل، يستيقظ ليجد حياته انقلبت بالكامل.\nزوجته التي أنهكها التعب والشكوى، تصبح فجأة زوجة مثالية.. لا تشكو.. لا تتعب.. ولا تنام!!!\nفي البداية يبدو كل شيء مثاليًا..\nثم يبدأ الغموض. صمت غير مريح.\nنظرات لا تُفهم، وتفاصيل تختفي بلا تفسير.\nالطمأنينة تتحوّل إلى خوف صامت.\nوما حدث ليس نعمة، ولا يمكن التراجع عنه بسهولة.\nكل إجابة تقوده إلى طريق أكثر خطورة، وكل تأخير يقرّبه من خسارة لا تُعوّض.\nفي النهاية، إما أن يكسر الوهم…\nأو يختار الاستمرار… حتى النهاية.", CategoryId = 1, ImageUrl = "/images/products/9789778203226.webp", Author = "معتز شرباش", PublishDate = new DateTime(2026, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789778203226", Pages = 306, Size = "14×20" },
            new { Id = 10, Name = "آخر رجال الهيلمان", Price = 300m, Stock = 10, Description = "ختفى ليلة تخرجه.\nسُجِّل ميتًا.\nثم عاد.\nلا ليعيش،\nبل ليواجه.\n\nعشرون عامًا من الصمت تُخفي مهمة سرية، وخيانة، وسرًا رقميًا تخشاه منظمة أقوى من دول.\nكل خطوة محسوبة.\nكل جرح مقصود.\n\nفي الشوارع، حرب بلا شهود.\nعمليات دقيقة بلا أثر.\n\nوبينما يضيق الخناق، تتكشف خطة لا تُرى،\nونهاية لا تشبه أي توقع.\n\n«رجال الهيلمان»\nعن الثمن الحقيقي للبطولة.", CategoryId = 3, ImageUrl = "/images/products/9789778203363.webp", Author = "يحيى صفوت", PublishDate = new DateTime(2026, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789778203363", Pages = 368, Size = "14×20" },
            new { Id = 11, Name = "أطلقني", Price = 330m, Stock = 10, Description = "رواية رومانسية ديستوبية من عالم سلسلة Shatter Me للكاتبة طاهرة ماڤي، ترجمة ضحى صلاح. حكاية عن حب يولد في عالم قاسٍ، وقوى خارقة تخيف أصحابها قبل الآخرين، وعن شجاعة أن تتحرر من الخوف.", CategoryId = 4, ImageUrl = "/images/products/9789778203134.webp", Author = "طاهرة ماڤي", PublishDate = new DateTime(2026, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789778203134", Pages = 240, Size = "14×20" },
            new { Id = 12, Name = "أفهم كلبك", Price = 130m, Stock = 10, Description = "الكلب اللي بيعض مش دايمًا شرس، واللي بيخاف مش دايمًا ضعيف، واللي بيتجاهلك مش دايمًا عنيد\".\nالكلب قصة حقيقية أشبه بقصصنا، تجارب، وملاحظة وحياة بيعيشها بتخليه يكتسب صفاته اللي بنشوفها.", CategoryId = 5, ImageUrl = "/images/products/9786339957543.webp", Author = "محمود فادي", PublishDate = new DateTime(2026, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9786339957543", Pages = 166, Size = "14×20" },
            new { Id = 13, Name = "أقرب إلى النور", Price = 240m, Stock = 10, Description = "حيث يتقاطع الحب مع الأذى، تنكشف هشاشة القلب وصلابته معًا. في تلك المساحة الرمادية بين القرب والخذلان، تبدأ الحكاية.\nبين الفوضى والهوس، تعيش امرأة ممزّقة بين مسؤوليات ثقيلة، وعلاقة تُربك صورتها عن نفسها وتعيدها مرارًا إلى الدائرة ذاتها.\nلا يأتي النضج كخلاصٍ مفاجئ، بل يتشكّل ببطء، عبر محاولات متعثّرة للفهم، وحياة يومية مليئة بالأسئلة.\n\nأقرب إلى النور..\nتغوص في المناطق الخفية للعلاقات، وتفكّك الروابط التي تصوغ اختياراتنا، حين نحب بالطريقة التي تعلّمنا بها البقاء.\n\nرواية لا تعد بالنجاة السهلة، بل بالوعي، والتصالح مع الذات، حين يصبح الألم مُعلّمًا لا سجنًا، وحين نعرف لماذا تألّمنا، لا فقط كيف؛\nلتبدأ رحلة حقيقية نحو التعافي… والاقتراب أكثر من النور.", CategoryId = 6, ImageUrl = "/images/products/9789778203110.webp", Author = "هدى عبدالمنعم", PublishDate = new DateTime(2026, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789778203110", Pages = 272, Size = "14×20" },
            new { Id = 14, Name = "الأفرنجى", Price = 350m, Stock = 10, Description = "تدور الرواية في القرن الثالث عشر، بعد هزيمة الحملة الصليبية وأسر عدد من الفرنجة في مصر.\nالبطل فارس أوروبي يقع في الأسر، يُنقل بين السجون، ويذوق الإهانة والعجز، ثم تنقلب حياته حين يخرج من الأسر إلى الحرية.\nوبسبب مرض يصيبه، يجد طريقه إلى الفسطاط، حيث تستقبله أسرة مصرية مسيحية، وتبدأ مرحلة جديدة من حياته.\nليتعرّف على مدينة نابضة، تتجاور فيها الكنيسة والمسجد والمعبد، ويخالط أطباء وعلماء ورجال دين، ويرى القاهرة والفسطاط من الداخل.\nلا كأرض عدو،\nبل كعالم إنساني نابض بالحياة.", CategoryId = 7, ImageUrl = "/images/products/9789778203141.webp", Author = "أيمن رجب طاهر", PublishDate = new DateTime(2026, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789778203141", Pages = 458, Size = "14×20" },
            new { Id = 15, Name = "على أوتار الباسنكوب", Price = 200m, Stock = 10, Description = "على أرض لم تعترف يومًا بالحدود.\nتدور حكاية لا تشبه ما قيل في الأخبار.\n\nفي قلب مثلث حلايب.\nحيث يعيش شعب البجا كما عاشوا دائمًا،\nبالرعي، بانتظار المطر.\nوبعلاقة قديمة مع الأرض لا تحتاج إلى خرائط.\n\nوحين يتغير المشهد، لا يتغير المكان فقط،\nبل تتولد الأسئلة. من نحن؟\nولمن ننتمي!!\n\nرواية عن الهوية حين تصبح عبئًا.\nوعن الأرض حين تطلب ثمن البقاء.\nوعن الإنسان حين يُجبر على الاختيار.\nدون أن يكون مستعدًا.\n\nحين يصبح الانتماء أصعب من الرحيل.\nوهل الوطن قرار أم قدر؟", CategoryId = 7, ImageUrl = "/images/products/9789778203370.webp", Author = "عبدالرحمن شاكر", PublishDate = new DateTime(2026, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789778203370", Pages = 242, Size = "14×20" },
            new { Id = 16, Name = "عجلة الزمن : التنين العائد (مجلدين)", Price = 875m, Stock = 10, Description = "في «التنين العائد»، الرواية الثالثة من ملحمة «عجلة الزمن»، يجد راند ألثور نفسه أمام خيار واحد لا مفر منه؛ أن يواجه مصيره أو يُصاب بالجنون وهو يحاول الهروب منه.\nالشتاء أوقف الحرب… لكنه لم يوقف الموت. الرجال يموتون في كل مكان وهم يهتفون باسم «التنين»، والكل يتساءل: أين هو المخلّص؟\nيقرر راند الانطلاق وحيدًا في رحلة يائسة نحو قلعة أسطورية لم تسقط قط. هناك، خلف جدران لا تُقهر، يقبع اختبار رهيب.\nالآن، يجب على مويرين ورفاقها خوض سباق محموم ضد الزمن ووحوش الظلام للحاق به، لأن فشل راند هذه المرة لا يعني الموت فحسب… بل يعني تسليم العالم لظلام أبدي.\nالنبلاء يتآمرون، والظلال تتحرك، والعالم يحبس أنفاسه… خطوة واحدة تفصل بين المخلّص المنتظر… والمجنون الذي قد يدمّر العالم.", CategoryId = 2, ImageUrl = "/images/products/9789778203127.webp", Author = "روبرت چوردان", PublishDate = new DateTime(2026, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789778203127", Pages = 982, Size = "14×20" },
            new { Id = 17, Name = "ألغاز وتسالي للكبار", Price = 120m, Stock = 10, Description = "كتاب ترفيهي للكبار يجمع الألعاب والألغاز والتحديات الذهنية، لساعات من التسلية وشحذ الذكاء والتركيز. يناسب القراءة الفردية أو قضاء وقت ممتع مع الأصدقاء والعائلة.", CategoryId = 3, ImageUrl = "/images/products/9786339957529.webp", Author = "نرمين صلاح الدين أحمد", PublishDate = new DateTime(2026, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9786339957529", Pages = 125, Size = "14×20" },
            new { Id = 18, Name = "الفم", Price = 165m, Stock = 10, Description = "رواية فلسفية للكاتب الليبي إبراهيم الكوني عن حب يتحدّى قوانين القبيلة الصارمة، فلا يبقى أمام البطل إلا الطاعة والتخلّي أو السقوط في «الفم»؛ الهاوية التي تبتلع من يتمرّد على قدر الصحراء. رحلة تتداخل فيها التضحية بصمت الرمال.", CategoryId = 8, ImageUrl = "/images/products/9789778203455.webp", Author = "د. إبراهيم الكوني", PublishDate = new DateTime(2026, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789778203455", Pages = 135, Size = "14×20" },
            new { Id = 19, Name = "المجاميع", Price = 180m, Stock = 10, Description = "من قرية المياسرة بدمياط إلى قلب لندن…\nحكاية رجل عادي..\nسحقه الفقر، واختبرته القسوة، وتعثر مرارًا..\nثم صعد بإرادته، وبطرق غير متساوية.\nمحمد يوسف البغدادي..\nليس استثناء، بل نموذجًا نراه كل يوم\nولا نعرف حكايته..\nرحلة عن الطموح حين يرفض الهزيمة،وعن الحياة حين ترفعك فجأة..\nثم تختبر قدرتك على البقاء..\nعن الإنسان، حين يصارع واقعه..\nويصنع مصيره بنفسه..", CategoryId = 1, ImageUrl = "/images/products/9789778203189.webp", Author = "محمد مصطفى عرفى", PublishDate = new DateTime(2026, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789778203189", Pages = 184, Size = "14×20" },
            new { Id = 20, Name = "إنطفاء مصباح", Price = 180m, Stock = 10, Description = "أجلسُ بصحبةِ قلمٍ فضيٍّ شُجَّ رأسُه، وجفَّ الجرحُ.\nأريدُ أن أحكي قبل أن يفرغ حبرُه.\nأجدُ نفسي أرسمُ مجددًا.\n\nأرسمُ أعينًا، وأبوابًا، وأمواجًا.\nأرسمُ شيخًا يحمل طفلًا لم يتقبّل فكرة انتهاء مدة اللعب.\nأرسمُ شابًا تائهًا، غارقًا في ملابس البالغين الفضفاضة.\nأرسمُ فندقًا يُعجب صاحبُه بازدحامه، ولا يفهم أن الزائر يبيت بضع ليالٍ ثم يرحل بلا عودة.\nأرسمُ صاحبَ سيركٍ يُلاعب قردًا.\nأرسمُ سريرًا، تحته مقبرةٌ تُدفن فيها الأحلام الضائعة.\n\nأتأملُ ما رسمتُه، فأجدني موجودًا في كل شيء.\nأنا الطفلُ، والشابُ، والشيخ.\nأنا صاحبُ الفندق وزبونُه.\nأنا الزائرُ والمقيم.\nأنا صاحبُ السيرك والمشاهد.\nأنا القردُ والطبلة.\nأنا الذي حفرتُ المقبرة، وأنا من بكيت.\nأنا من دفنتُ الأحلام بيدي.\n\nيئستُ من تحقيقها.\nتخلّيتُ بعدما تمسّكت.\nأطفأتُ المصباح، فاستحالت الألوانُ إلى أسودَ قاتم.\nحاولتُ أن أمحو آثارَ الأحلام، لكنها كانت تعود بعد النوم.\nتدبّ فيها الحياةُ لدقائق، لتذكّرني بأيامٍ ولّت،\nوتتساءل في أسف:\nبأيِّ ذنبٍ دُفِنتُ؟", CategoryId = 6, ImageUrl = "/images/products/9789778203264.webp", Author = "أحمد عصام الدين", PublishDate = new DateTime(2026, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789778203264", Pages = 172, Size = "14×20" },
            new { Id = 21, Name = "بألف طريقة مختلفة", Price = 400m, Stock = 10, Description = "تخيّل عالمًا ترى فيه الحقيقة بلا أقنعة.\nترى الناس كما هم فعلًا.\nمشاعرهم، نواياهم، أسرارهم، وحتى أكاذيبهم.\n\nمن العيش في عزلة خلف نظارات شمسية وقفازات، إلى حياة تفيض فيها الألوان بكل درجاتها، تبدأ أليس رحلة البحث عن ذات لا تذوب في الآخرين.\nرحلة شاقة نحو الفهم.\nنحو القبول.\nونحو النجاة.\n\nهذه ليست رحلة إلى الخارج، بل إلى الداخل.\nحيث المواجهة الأصعب.\n\nرواية عن رؤية ما لا يراه الآخرون.\nوعن عالم واحد… يمكن أن يُرى بألف طريقة مختلفة.", CategoryId = 6, ImageUrl = "/images/products/9789778203103.webp", Author = "سيسيليا اهيرن", PublishDate = new DateTime(2026, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789778203103", Pages = 360, Size = "14×20" },
            new { Id = 22, Name = "بعض ما ورد بشأنها", Price = 230m, Stock = 10, Description = "زائرة مجهولة بفستان زفاف.\nبلاغ مرتبك عن جريمة قتل.\nواختفاء يربك كل ما يبدو واضحًا.\n\nمن شذرات متفرقة ومعطيات ناقصة، أجد نفسي مدفوعةً إلى خوض تجربتي الأولى في الكتابة.\nلا بوصفها بحثًا عن حل.\nبل كتجربة يحركها الفضول والشك.\n\nالنص لا يعد بإجابات.\nولا يمنح يقينًا.\nإنه اقتراب بطيء من لغز.\nواعتراف بأن بعض القصص لا تُحكى… بل تُعاش.\n“و.م”", CategoryId = 6, ImageUrl = "/images/products/9789778203356.webp", Author = "رامي احمد مصطفى", PublishDate = new DateTime(2026, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789778203356", Pages = 248, Size = "14×20" },
            new { Id = 23, Name = "تحليق إيكاروس", Price = 400m, Stock = 10, Description = "لا تؤدّي كلُّ الطرق إلى النجاة، فأحيانًا ما تكون مجرّد بداية، كأغنيةٍ بعيدة تأتي من مكانٍ مجهول، ثم تعلو.. حتى تصير صراخًا يسكن الرأس.\nفي «تحليق إيكاروس» لا تقف الكارثة عند حدود بلدة صغيرة، بل تبدأ من داخلها؛ من رغبةٍ جارفةٍ في الخلاص، من حلمٍ بأن يصبح المرء ذو قيمة، ومن خطوةٍ واحدة نحو ضوء يبدو جميلًا، يعد بالأمل.. ويُخفي الاحتراق.\nولا تبدأ الحكاية بطفلٍ صغير يختفي دون أثر، أو بوحشٍ يخرج من الظلام، بل بشابٍّ.. يظن أن الخروج من البلدة هو النجاة، وأن الموسيقى هي الوسيلة المثلى لتحقيق هدفه.\nلكن بعض الأبواب لا تُفتح إلا لتريك ما لا ينبغي أن يُرى، وبعض الفرص تعدنا بالأمل.. وتُخفي في باطنها العذاب.\n«تحليق إيكاروس» ليست مجرّد رواية عادية، بل عمل سيترك في قلبك ندبةً لا تُرى.", CategoryId = 3, ImageUrl = "/images/products/9789778203257.webp", Author = "كيتلين شنايدرهان", PublishDate = new DateTime(2026, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789778203257", Pages = 364, Size = "14×20" },
            new { Id = 24, Name = "تخيلني", Price = 455m, Stock = 10, Description = "نغوص مع وارنر وكينجي في بحر من المشاعر الجياشة والتفاني المطلق، بينما يواجهان سباقًا مع الزمن لإنقاذ جولييت والحفاظ على حياتها. تدخل جولييت في غيبوبة غامضة، تاركة خلفها فراغًا ثقيلًا يدفع وارنر وكينجي إلى مواجهة قرارات مصيرية.\n\nفي الوقت نفسه، يتصاعد التوتر مع احتجاز أندرسون لجيمس وآدم وبقية أطفال القادة العُليا كرهائن، ما يجعل التحديات أكثر تعقيدًا وخطورة. يزخر هذا الجزء بالمنعطفات المدهشة والأحداث غير المتوقعة التي تطرح أسئلة ملحّة: هل ستنجو جولييت؟ وكيف سيتمكن أصدقاؤها من تحرير الرهائن ومواجهة أندرسون؟ والأهم… هل سينجحون في الإطاحة بنظام «إعادة التأسيس» إلى الأبد؟", CategoryId = 4, ImageUrl = "/images/products/9789778202571.webp", Author = "طاهرة ماڤي", PublishDate = new DateTime(2026, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789778202571", Pages = 430, Size = "14×20" },
            new { Id = 25, Name = "تماثيل الملح", Price = 200m, Stock = 10, Description = "ما خُتِمَ بالملح… لا يذوب\nفي بلدةٍ ساحليةٍ يبدو كلُّ شيءٍ مألوفًا، حتى تبدأ الأمور بالتغيّر.\nتظهر تماثيل ملح في كل مكان، على الشواطئ وفي الزوايا، بلا صانعٍ معروف، ولا سببٍ مقنع.\nيحاول الجميع التعامل معها كأسطورةٍ قديمة، أو كوسيلة دعاية جديدة، قبل أن تتطوّر الأمور، وينتشر الملح ليفرض سطوته على كل شيء، كلما ظنّ الجميع أن الأمر قد انتهى.\n\nسرعان ما يجد سليم خطّاب، كاتب الرعب الشهير، الذي يعاني من مشكلات لا يمكن لأحد تصوّرها، نفسه متورّطًا في قلب الرعب؛ ويجد نفسه محاصرًا بأسئلةٍ عليه العثور على إجابتها.\nما علاقة هذه التماثيل برواياته؟ ولماذا يبدو أن البلدة تتصرّف كمن يُخفي لعنةً قديمة؟ وهل سيحتاج للبحث عن الناجين من الأساطير المرعبة ليجد ضالته بينهم؟\n\nقبل أن يدرك أن كل إجابة تقوده إلى سؤالٍ أشدّ ظلمة، وكل خطوة تقوده نحو حقيقةٍ لا يرغب في معرفتها… حيث لا يكون الماء ماءً فقط، ولا الملح ملحًا فحسب.\n\nفي «تماثيل الملح»، تذوب الرواية بين الأسطورة القديمة، وتتداخل مع الواقع، حتى لا تعود قادرًا على الفصل بين ما تراه… وما يريدك الملح أن تراه.", CategoryId = 9, ImageUrl = "/images/products/9789778203240.webp", Author = "محمد عصمت", PublishDate = new DateTime(2026, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789778203240", Pages = 198, Size = "14×20" },
            new { Id = 26, Name = "جريمة عائلية", Price = 490m, Stock = 10, Description = "ديسمبر 2003: يُعثر على زوج أم المخرج السينمائي غاي هوارد ميتًا في حديقة منزل العائلة في لندن، وتقول والدته ونصفا شقيقتيه إنهن لم يرين شيئًا. بعد سنوات يعيد مسلسل وثائقي فتح القضية فتتكشف الأسرار أمام الجميع، وتبدو الحقيقة أقرب إلى البيت مما يُتوقع. رواية جريمة وتشويق بأسلوب الرسائل والمقابلات والوثائق.", CategoryId = 3, ImageUrl = "/images/products/9789778203158.webp", Author = "كارا هانتر", PublishDate = new DateTime(2026, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789778203158", Pages = 578, Size = "14×20" },
            new { Id = 27, Name = "جنينة المحروقي", Price = 260m, Stock = 10, Description = "غادر كريم بيته طفلًا في ليلة بلا تفسير وبأمر من أمه، ليقضي سنوات طويلة في الغياب محمّلًا بذنب لا يهدأ، قبل أن يعود عودة وحيدة لدفنها. يعود إلى المربع السكني الذي لم يتغير في شكله، لكن أهله لم يعودوا كما كانوا، وتظل جنينة المحروقي في المنتصف صامتة، مغلقة، ومراقَبة. يكتشف كريم جيرانًا لا يتذكرهم، وتصرفات بلا تفسير، أكياسًا سوداء، روائح بخور، مفاتيح بلا أبواب، وليلة سبت لا يُسمح له أن يبقى فيها. وحين يكتشف أنه كان حاضرًا وهو غائب، وأن وفاة أمه ليست نهاية بل بداية، يتحول الفضول إلى خوف، والخوف إلى مواجهة مع أسطورة قديمة، وروح لم تغفر لنفسها، وسكان يحمون سرًا مشتركًا بأي ثمن. إنها رواية نفسية مظلمة عن الفقد، والذنب، والأماكن التي تطالبك بأغلى ما تملك قبل أن تسمح لك بالرحيل.", CategoryId = 9, ImageUrl = "/images/products/9789778203318.webp", Author = "يحيى صفوت", PublishDate = new DateTime(2026, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789778203318", Pages = 302, Size = "14×20" },
            new { Id = 28, Name = "دكستر في الظلام", Price = 435m, Stock = 10, Description = "مثَّل الراكِب المُظلِم داخله وعدًا ثابتًا؛ صوتٌ يقوده، وجوعٌ لا يضل، وظلٌّ يهبه معنى.. ولو كان معنى مُلطَّخًا بالدماء.\nثم حدث ما لا يُغتفر؛ وصمت الظلام.\nلا اندفاع، ولا همس، ولا نشوة.. فقط فراغٌ بارِد يتَّسع في صدر دكستر، كقبرٍ مفتوحٍ ينتظِر صاحبه.\nلكن الصمت لا يعني الخلاص؛ فأحيانًا.. يكون فخًا، وأحيانًا أخرى يكون إعلانًا بأن شيئًا أقدم، وأقسى، قد انتبه إليه أخيرًا.\nشيء لا يُريد منه القتل.. بل يُريده هو!\nبين صفحات هذا الكِتاب، لا يُطارِد دكستر قتلةً فحسب؛ بل سؤالًا ينهش روحه؛ ماذا يتبقّى من الوحش.. حين يُسلب منه ظلامه؟\nدكستر في الظلام ليست مُجرَّد رواية.. بل سقوطٌ بطيء في ظلامٍ دامس لا قاع له.", CategoryId = 3, ImageUrl = "/images/products/9789778203196.webp", Author = "چيف ليندسي", PublishDate = new DateTime(2026, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789778203196", Pages = 420, Size = "14×20" },
            new { Id = 29, Name = "دونوس", Price = 180m, Stock = 10, Description = "بدأ كلُّ شيءٍ بصداعٍ غريب.\nظلٌّ أسود يلاحق رامي، وإحساسٌ دائم بالمراقبة.\nصرخةٌ، نزيفٌ غامض، ثم موت.\nلكن القصة لا تنتهي هنا.\n\nبعد دفنه، تصل رسائل من هاتفه.\nقبرٌ يختفي.\nوصورةٌ تكشف ظلًّا غامضًا خلفه.\nعودةٌ لم يكن ينبغي أن تحدث.\n\nحياةُ عائلةٍ تنقلب إلى لغز.\nأصدقاءُ يواجهون أسرارًا خطيرة.\nوشخصياتٌ تظهر وتختفي، بينما اسمٌ واحد يتردد في كل مكان: دونوس.\n\nمن الذي عاد فعلًا؟\nوما هو كتاب الهاشكيلا؟\nومن يقود اللعبة، ومن يحاول حماية الأرض؟\n\nروايةٌ تشويقية عن أسرارٍ قديمة،\nوصراعٍ يتجاوز الموت نفسه.", CategoryId = 9, ImageUrl = "/images/products/9789778203325.webp", Author = "حسن الحلبي", PublishDate = new DateTime(2026, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789778203325", Pages = 224, Size = "14×20" },
            new { Id = 30, Name = "طه حسين الأيام المنسية", Price = 300m, Stock = 10, Description = "كتاب طه حسين: الأيام المنسية، يعيد فتح الصفحات التي لم تُكتب..\nويكمل ما توقف عنده عميد الأدب العربي طه حسين في سيرته الأشهر.\nليست سيرة تقليدية، بل كشف مباشر عبر رسائل خاصة وأوراق شخصية ونصوص لم تُنشر من قبل.\nكتاب يضعك أمام طه حسين الحقيقي\nبعقله وشكّه وإرادته التي صنعت نورًا من العتمة.", CategoryId = 7, ImageUrl = "/images/products/9789778203332.webp", Author = "إبراهيم عبدالعزيز", PublishDate = new DateTime(2026, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789778203332", Pages = 372, Size = "14×20" },
            new { Id = 31, Name = "عاصفة السيوف سوفت كڤر ( النسخة العالمية)", Price = 1250m, Stock = 10, Description = "ما زالت حرب الملوك الخمسة مشتعلةً، تعاني ويلاتها جميع أنحاء الممالك السبع إلا قليلًا. على العرش الحديدي يجلس الملك الصبي الغاشم جوفري، فيما يسعى جدّه اللورد تايوين لانستر، يدُ الملك، لتأمين حكمه، ومن ثم تأمين السلطة لعائلة لانستر، مخططًا للقضاء على الملك ستانيس باراثيون الذي خرج مدحورًا من معركة الماء الأسود، وعلى الذئب الصغير روب ستارك الذي يقود حملةً في غرب البلاد رغم أنه فقد وطنه في الشمال.\n\nوفي تلك الأثناء تشقّ الملكة المنفية دينيرس تارجاريَن طريقها في قارّةٍ أخرى تُغرقها الدماء، بغية تحرير مئات الآلاف من العبيد والحصول على جيشٍ تستعيد به مملكتها، ومعها التنانين الثلاثة الحيّة الوحيدة في العالم.\n\nوفي الشمال يتحرّك جيشٌ جرّار من الهمج استعدادًا للهجوم على الجدار وغزو الممالك السبع، جيشٌ انضمّ إليه رجل حرس الليل جون سنو جاسوسًا، ولو أنّ شيئًا أسوأ منه يتقدّم من أقصى الشمال، العدوّ الحقيقي الذي ينشغل عنه الجميع تقريبًا بقتالهم، وقد لا تقدر جيوش الأرض كلّها على ردعه.", CategoryId = 2, ImageUrl = "/images/products/9789778203219.webp", Author = "چورچ ر.ر مارتن", PublishDate = new DateTime(2026, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789778203219", Pages = 1534, Size = "14×20" },
            new { Id = 32, Name = "عباقرة الكتابة", Price = 250m, Stock = 10, Description = "الحكي أقدم وسيلة ترفيه وتعلّم في التاريخ، قبل المسرح، وقبل الكتابة، وقبل كل شيء. القصص ملأت الأديان، وشكّلت وعي البشر.\nلكن لماذا تنجح بعض القصص وتفشل أخرى؟ وما الذي يصنع الكاتب العظيم؟ الشغف، الالتزام، وحب المعرفة.\nصفات جمعت بين كتّاب وصلوا إلى قمة الإبداع، وأثبتوا أن اسم الكاتب يمكن أن يكون عنصر جذب لا يقل عن النجوم.\nنجيب محفوظ، كريستوفر نولان، وجي كي رولينج. عباقرة جمعوا بين الفن والنجاح الجماهيري، خاطبوا القلوب والعقول، وأتقنوا هندسة المشاعر.\nدروس يمكن تعلّمها، لكن يبقى السؤال: ما ثمن العبقرية، وكيف نصل إليها؟", CategoryId = 8, ImageUrl = "/images/products/9789778203202.webp", Author = "طاهر المعتز بالله", PublishDate = new DateTime(2026, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789778203202", Pages = 312, Size = "14×20" },
            new { Id = 33, Name = "غيط النوبي", Price = 200m, Stock = 10, Description = "بحيّ الأزبكية، نهايةَ القرنِ التاسعَ عشرَ،\nواقعةٌ من أغربِ الوقائع التي شهدتها المحروسة.\nذكرها التاريخُ باسم: يوم الفرجة،\nثم محا أثرها من أوراقه.\n\nما بين خوجةٍ ريفيٍّ هرب من الماضي،\nوامرأةٍ ذات ماضٍ ملتبسٍ سحرها الشيطان،\nوجريمةِ قتلٍ بلا قتيل،\nوصعلوكٍ يمتطي طاولاتِ المقاهي،\nيُقصّ حقيقةَ يوم الفرجة،\nالتي لا يعلمها غيره.\n\nتسافر الروايةُ عبر الزمن إلى أيامِ القاهرة الخديوية،\nوتكشف خبايا ما حدث في ذلك اليوم المشؤوم،\nفي رحلةٍ اجتمع فيها الأضدادُ على حبٍّ محرَّم وسرٍّ ملعون،\nفي وثيقةٍ يرفضها التاريخ،\nولكن لا ينكرها من شهدها.", CategoryId = 3, ImageUrl = "/images/products/9789778203301.webp", Author = "محمد فوزي عبد الرحيم", PublishDate = new DateTime(2026, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789778203301", Pages = 187, Size = "14×20" },
            new { Id = 34, Name = "قصر البارون", Price = 200m, Stock = 10, Description = "بلاغ عن حريق لا يترك أثرًا.\nوقصر يخفي أكثر مما يُظهر.\nتحقيق في واقعة غامضة يقود إلى لغز يتجاوز المنطق والزمن.\n\nغرفة مرايا تفتح أبوابًا غير متوقعة.\nأزمنة تتقاطع على نحو غير متوقع.\nوتاريخ يسير في مسارات لم تحدث يومًا.\nكل انتقال يكشف سرًا جديدًا.\nوكل محاولة للعودة تقود إلى زمن أكثر خطورة.\n\nرواية تمزج التحقيق بالغموض.\nوتطرح سؤالًا واحدًا يلاحق القارئ حتى النهاية.\nهل القصر شاهد على ما حدث… أم صانع له؟", CategoryId = 3, ImageUrl = "/images/products/9789778203233.webp", Author = "محمد كامل", PublishDate = new DateTime(2026, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789778203233", Pages = 216, Size = "14×20" },
            new { Id = 35, Name = "كل الظلال التي نخفيها", Price = 230m, Stock = 10, Description = "على شاطئ بورتسموث، وبين غرفة ضيقة ومرافقة عجوز، تُجبر آية على مواجهة ذاتها.\nهروب من وطن موجوع، وعائلة مثقلة بالفقد، وزواج بلا صوت.\n\nصوت من الماضي، مساحة مفتوحة للاعتراف بكل ما صمتت عنه طويلًا.\nووجه من الحاضر يعيد ترتيب فوضى قلبها..\n\nإنها ليست رواية، بل سيرة وجع عربي ممتد.\nذاكرة حروب.\nمنافي أقسى من الغربة.\nونساء يحملن الهزيمة في أجسادهن، وفي أصواتهن المكبوتة.", CategoryId = 6, ImageUrl = "/images/products/9789778203349.webp", Author = "سوزان خلقي", PublishDate = new DateTime(2026, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789778203349", Pages = 254, Size = "14×20" },
            new { Id = 36, Name = "لستُ الأخيرة", Price = 260m, Stock = 10, Description = "ليست كل الحكايات تُروى بصوت واحد.\nوليست كل النساء ينجون…\nفي لستُ الأخيرة\nتتقاطع حيوات نساء من أزمنة وأماكن مختلفة..\nروما في القرن السابع عشر والإسكندرية في الحاضر.\nامرأة تصنع خلاصها بيديها.\nوأخرى تحاول إنقاذ غيرها قبل أن يفوت الأوان.\nقصص عن العنف، عن النجاة، وعن الثمن الذي تدفعه النساء حين يقررن ألا يكنّ الضحية التالية..\nرواية عن قوة تُولد من العجز،وعن رحمة قد تتحول إلى حمل ثقيل، وعن سؤال يرفض أن يختفي!!\nهل تنتهي الدائرة،أم أن هناك دائمًا ضحية جديدة؟", CategoryId = 1, ImageUrl = "/images/products/9786339957536.webp", Author = "كنزي مدبولي", PublishDate = new DateTime(2026, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9786339957536", Pages = 272, Size = "14×20" },
            new { Id = 37, Name = "ما وراء الإبعاد", Price = 165m, Stock = 10, Description = "في اللحظة التي تظن فيها أنك تمسك هذا الكتاب، تخبرنا الفيزياء أن هناك نسخة أخرى منك ربما اختارت ألا تقرأه، ونسخة ثالثة لم تولد من الأساس... نحن نعيش في سجن من ثلاثة جدران نسميه \"الواقع الحقيقي\"، لكن العلم من وراءها يهمس بأن هذا السجن له أحد عشر بابًا مفتوحًا لا نراها!\n\nفي هذا الكتاب، سأصطحبك معي في رحلة ذهنية مذهلة عبر فيزياء الأبعاد العلوية... رحلة تبدأ من الصفر، وتصعد بك عبر درجات المكان والزمان، لتكشف لك هندسة الكون الخفية كما لم ترها من قبل، وتجيب عن أسئلة لم تخطر ببالك...\n\nهل الزمن مجرد وهم؟ وهل الماضي والمستقبل موجودان الآن معًا في مكان ما؟ كيف يفسر العلم مفهوم \"طي الواقع\"؟ وما هي العلاقة بين \"الأكوان الموازية\" ومعضلة الاختيار والاحتمالات؟ \n\nلماذا يرانا الجن ولا نراهم؟ (الإجابة هندسية بحتة!)، وكيف تلتقي أحدث نظريات \"الأوتار الفائقة\" مع حلول أعمق الألغاز الحياتية في نقطة واحدة؟\n\nهذا ليس مجرد كتاب فيزياء تقليدي... إنه تجربة فكرية وفلسفية فريدة تحاول كسر الزجاج الذي يفصل بين عقولنا وبين الحقيقة الكبرى... وأعدك أنك بعد قراءة الصفحة الأخيرة، لن تنظر إلى العالم – أو إلى نفسك – بنفس الطريقة أبدًا...", CategoryId = 2, ImageUrl = "/images/products/9789778203387.webp", Author = "محمود علام", PublishDate = new DateTime(2026, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789778203387", Pages = 156, Size = "14×20" },
            new { Id = 38, Name = "مملكة النساء", Price = 300m, Stock = 10, Description = "منذ أكثر من ثلاثة آلاف عام، وفي إحدى قرى مصر، توارث الناس حكايات عن مدينة كاملة اختفت من كتب التاريخ، مدينة عاشت زمن الاضطراب الذي شهدته البلاد في عهد الملك رمسيس الثالث، حين اجتاحت قبائل أجنبية تُدعى المشوش أطراف مصر، ونشرت الخراب والفساد بين القرى والبلدان، فذُبح رجال المدينة في معركة دامية، وتُركت نساؤها وحدهن في مواجهة الخوف والجوع والمجهول؛ لم يكنّ ملكات ولا أميرات، بل نساءً عاديات، منهن من حاولت النجاة بالفرار، ومنهن من أشعلت ثورة الجياع، ومن تشبثت بالسحر بحثًا عن طوق نجاة أخير.\n\nمملكة النساء ليست أسطورة، بل رواية مستوحاة من حكايات حقيقية ما زال أهل القرية يروونها حتى اليوم، رغم أنها لم تُذكر في أي كتاب تاريخي، رواية عن الصمود، وعن نساء واجهن وحدهن زمن الانهيار، وكتبن حكاياتهن، ثم اختفين من التاريخ.", CategoryId = 7, ImageUrl = "/images/products/9789778203271.webp", Author = "مصطفى قمري", PublishDate = new DateTime(2026, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789778203271", Pages = 368, Size = "14×20" },
            new { Id = 39, Name = "نار بلا شرار", Price = 420m, Stock = 10, Description = "سفينة غارقة، وأسرار لم يعد ممكنًا إخفاؤها.\nبين سكان خائفين، ومرتزقة يبحثون عن النجاة…\nمادرا تتناقص، وأنفاق غامضة…\nقرار قد ينقذ الجميع، أو يحرق كل شيء…\nهذه ليست نهاية الرحلة… هذه لحظة الاختبار الحقيقي.\nهل يواجه آدم ثمن اختياره؟\nماذا حلّ بروان؟\nوهل يعود مايك…؟\nمن سينجو؟\nومن ستبتلعه النار؟", CategoryId = 2, ImageUrl = "/images/products/9789778203288.webp", Author = "د. خولة حمدي", PublishDate = new DateTime(2026, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789778203288", Pages = 448, Size = "14×20" },
            new { Id = 40, Name = "نبضات معدنية", Price = 165m, Stock = 10, Description = "هل تسكن الأحلامُ الدوائرَ الكهربائية؟\nوهل يمكن لقلبٍ من معدنٍ أن ينبض بالحب أو الخوف؟\n\n«نبضات معدنية»\nرحلةٌ استثنائية تتجاوز حدود الخيال العلمي التقليدي،\nتدخل بنا إلى المنطقة الضبابية الفاصلة بين الإنسان والآلة.\n\nليست مجرد حكايات عن المستقبل،\nبل مرآة تعكس مخاوفنا وأحلامنا وتساؤلاتنا الوجودية.\n\nإنها دعوة لإعادة تعريف ما يعنيه أن تكون «إنسانًا» في عالمٍ تتلاشى فيه الفوارق،\nوتتحول فيه المشاعر إلى شفرات،\nوتُترجم الأحلام إلى دوائر كهربائية.", CategoryId = 2, ImageUrl = "/images/products/9789778203097.webp", Author = "احمد صلاح المهدى", PublishDate = new DateTime(2026, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789778203097", Pages = 136, Size = "14×20" },
            new { Id = 41, Name = "هبوط حر", Price = 130m, Stock = 10, Description = "«هبوط حُرّ»\nعن الإنسان حين يُنزَع عنه الأمان: أمان الجسد، والذاكرة، والهوية، والاختيار.\n\nهنا لا يحدث الانهيار دفعةً واحدة، بل تدريجيًا، منطقيًا، وبهدوءٍ مرعب.\n\nالعالم لا يُدمَّر بالقنابل فقط، بل بالروتين، والطاعة، والخوف، والرغبة في النجاة الفردية.\nالناس يعتادون الرائحة الكريهة، ويعتادون العيش داخل الصَدَفة، ويعتادون أن يُدفنوا أحياء، وأن يُمحى ماضيهم، وأن يُدار وعيهم، وأن يُختزلوا إلى «وحدات».\nولا تحتاج السلطة هنا إلى قسوةٍ مباشرة دائمًا؛ يكفي أن تُقنع الناس أنه «ليس في الإمكان أبدع مما كان».\nوالإنسان لا يُهزم لأنه ضعيف، بل لأنه يوافق… ثم يُخفي عن نفسه أنه وافق.\nوالنهايات ليست صادمة بقدر ما هي كاشفة: العالم لا يسقط فجأة… بل يسقط سقوطًا حرًا، والإنسان يعتاد أن يسقط معه دون حتى أن يصرخ.", CategoryId = 1, ImageUrl = "/images/products/9789778203394.webp", Author = "حسام مصطفي ابراهيم", PublishDate = new DateTime(2026, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789778203394", Pages = 112, Size = "14×20" },
            new { Id = 42, Name = "وليمة للغربان (النسخة العالمية)", Price = 990m, Stock = 10, Description = "الجزء الرابع من سلسلة «أغنية الجليد والنار» للكاتب چورچ ر.ر مارتن، رواية فانتازيا ملحمية تتشابك فيها الصراعات على العروش والتحالفات والخيانات. النسخة العالمية.", CategoryId = 2, ImageUrl = "/images/products/9789778203417.webp", Author = "چورچ ر.ر مارتن", PublishDate = new DateTime(2026, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789778203417", Pages = 1098, Size = "14×20" },
            new { Id = 43, Name = "أقسى من الموت", Price = 130m, Stock = 10, Description = "ريم امرأة تعيش وحدها وتواجه الألم والفقد، إلى أن تضعها مواجهة غير متوقعة أمام أسطورة قديمة تتداولها الحكايات، فتبدأ في تتبّع خيوط الحقيقة. رواية تمزج الغموض بالخيال، بنهاية تحمل مفاجأة.", CategoryId = 1, ImageUrl = "/images/products/aqsa-min-almawt.webp", Author = "محمد عصمت", PublishDate = new DateTime(2026, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate },
            new { Id = 44, Name = "ساعة الذئب", Price = 130m, Stock = 10, Description = "ساعة الذئب هي الساعة التي تسبق الفجر، حين يبلغ الظلام أشدّه ويبدو كل شيء ممكنًا. رواية رعب وتشويق للكاتب خالد أمين، من إصدارات دار كيان للنشر.", CategoryId = 1, ImageUrl = "/images/products/saat-al-thib.webp", Author = "خالد أمين", PublishDate = new DateTime(2026, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate }
        );
